 view=load(D/'configs/data_v1/training_view_v1.json');schema=load(P/'schema.json');entries=load(D/'workflows/screening/registry/label_registry_v2.json')['entries'];registry={e['registry_id']:e for e in entries};meta={f['field_key']:f for f in schema['fields']};fields=[]
 for f in view['fields']:
  if f['group']!='P' or not f.get('enabled',True):continue
  m=meta.get(f['field_key'],{});e=registry.get(f.get('registry_id'),{});name=f['field_key'];m=m or (dict(family='bonding',level='pair',source_path='r73 directed-pair orbital channel sum',physical_policy_status='ACTUAL_TARGET_CONDITION_SOURCE_ENABLED') if f.get('registry_id')==73 else {})
  fields.append(dict(field_key=name,target_id=f.get('target_id'),registry_id=f.get('registry_id'),unit=f.get('unit',m.get('unit')),family=m.get('family'),level=m.get('level'),selectors=f.get('selectors'),source_path=m.get('source_path',e.get('source_path')),definition=e.get('canonical_target'),method=e.get('method'),actual_task_charge=e.get('charge'),environment=e.get('context'),electronic_state=e.get('electronic_context'),geometry_route=e.get('geometry_context'),coordinate_atom_convention='source_to_M mapping for each actual task; vectors/tensors require applicable frame policy',physical_policy=m.get('physical_policy_status'),mask_reasons=f.get('exclusion_reasons',[]),derived_from=e.get('derived_from'),dedup_of=e.get('dedup_of'),notes=e.get('notes'),source_precision=dict(value=None,reason='Printing,convergence and generator precision registered separately in stage2; FP64 container is not accuracy evidence'),program_version=dict(value=None,reason='Source task/version provenance to be resolved for frozen pairs; not inferred from library version')))
